-- OWNER, READ ONLY. Exercises every currently mapped active Retail FO. Compare protected digests with 01.
begin transaction read only;
do $verify$ declare fo record; result jsonb; expected bigint;begin
if not exists(select 1 from pg_proc where oid=to_regprocedure('public.retail_unified_owner(uuid,timestamptz)') and md5(replace(prosrc,E'\r\n',E'\n'))='a62460b7543b8b131593494af1ba610a' and prosecdef and provolatile='s' and exists(select 1 from unnest(proconfig) cfg where regexp_replace(cfg,'[[:space:]]','','g')='search_path=pg_catalog,public')) then raise exception 'Reviewed ownership helper missing or changed; do not install against drift';end if;
if has_function_privilege('anon','public.retail_unified_owner(uuid,timestamptz)','EXECUTE') or has_function_privilege('authenticated','public.retail_unified_owner(uuid,timestamptz)','EXECUTE') then raise exception 'Ownership helper public EXECUTE drift; inspect existing security first';end if;
perform t.id,t.employee_code,t.full_name,t.state,t.role,t.business,t.is_active,t.status from public.profiles t where false;
perform t.id,t.store_code,t.store_name,t.state,t.status from public.reliance_retail_store_master t where false;
perform t.id,t.zone_name,t.state,t.status from public.reliance_retail_zones t where false;
perform t.id,t.zone_id,t.fo_profile_id,t.effective_from,t.effective_to,t.status from public.reliance_retail_zone_fo_assignments t where false;
perform t.retail_store_id,t.attendance_date,t.class,t.credit,t.superseded_at from public.retail_employee_daily_attendance t where false;
perform t.retail_store_id,t.aop_class,t.hk_count,t.mepc_count,t.mepc_cycle_anchor,t.effective_from,t.effective_to,t.superseded_at from public.retail_attendance_aop_versions t where false;
if not exists(select 1 from supabase_migrations.schema_migrations where version='20261030170000' and cardinality(statements)=1 and md5(replace(statements[1],E'\r\n',E'\n'))='970d3b52d83453d5d3ce14730f5c8700') then raise exception 'FO self reader migration ledger mismatch';end if;
if not exists(select 1 from pg_proc where oid=to_regprocedure('public.rpc_retail_fo_self_snapshot(uuid,date,date)') and prosecdef and provolatile='s' and md5(replace(prosrc,E'\r\n',E'\n'))='f7aaf33ced6aed3ec0830fdd1b4988db' and exists(select 1 from unnest(proconfig) cfg where regexp_replace(cfg,'[[:space:]]','','g')='search_path=pg_catalog,public')) then raise exception 'FO self reader function drift';end if;
if has_function_privilege('anon','public.rpc_retail_fo_self_snapshot(uuid,date,date)','EXECUTE') or has_function_privilege('authenticated','public.rpc_retail_fo_self_snapshot(uuid,date,date)','EXECUTE') or not has_function_privilege('service_role','public.rpc_retail_fo_self_snapshot(uuid,date,date)','EXECUTE') then raise exception 'FO self reader EXECUTE ACL mismatch';end if;
for fo in select distinct p.id from public.profiles p join public.reliance_retail_zone_fo_assignments a on a.fo_profile_id=p.id where p.is_active and upper(coalesce(p.status,'Active'))='ACTIVE' and regexp_replace(upper(p.role),'[^A-Z0-9]','','g') in ('FO','FIELDOFFICER') and regexp_replace(upper(p.business),'[^A-Z0-9]','','g') in ('RELIANCE','RELIANCERETAIL') and a.effective_from<=now() and (a.effective_to is null or now()<a.effective_to) loop
 result:=public.rpc_retail_fo_self_snapshot(fo.id,(now() at time zone 'Asia/Kolkata')::date,(now() at time zone 'Asia/Kolkata')::date);
 if result->>'scope'<>'FO_SELF' or result->>'actor_id'<>fo.id::text or jsonb_array_length(result->'fos')<>1 or result->'fos'->0->>'id'<>fo.id::text then raise exception 'FO identity isolation failed';end if;
 if exists(select 1 from jsonb_array_elements(result->'self_days') d where d->>'fo_id' is distinct from fo.id::text or public.retail_unified_owner((d->>'store_id')::uuid,least(now(),((d->>'date')||'T23:59:59+05:30')::timestamptz))->>'fo_profile_id' is distinct from fo.id::text) then raise exception 'Dated attendance ownership isolation failed';end if;
 if exists(select 1 from jsonb_array_elements(result->'self_current_stores') s where s->'current_owner'->>'fo_profile_id' is distinct from fo.id::text) or exists(select 1 from jsonb_array_elements(result->'assignments') a where a->>'fo_profile_id' is distinct from fo.id::text) then raise exception 'Current store/assignment isolation failed';end if;
 select count(*) into expected from public.reliance_retail_store_master s where public.retail_unified_owner(s.id,now())->>'fo_profile_id'=fo.id::text;
 if jsonb_array_length(result->'self_current_stores')<>expected then raise exception 'Own assigned store count mismatch';end if;
end loop;end;$verify$;
select version,name,md5(replace(statements[1],E'\r\n',E'\n'))='970d3b52d83453d5d3ce14730f5c8700' as source_exact_match from supabase_migrations.schema_migrations where version='20261030170000';
select p.id as fo_profile_id,jsonb_array_length(r->'self_current_stores') as own_stores,jsonb_array_length(r->'assignments') as own_assignments,jsonb_array_length(r->'self_days') as authorized_store_class_days from public.profiles p cross join lateral (select public.rpc_retail_fo_self_snapshot(p.id,(now() at time zone 'Asia/Kolkata')::date,(now() at time zone 'Asia/Kolkata')::date) r) q where p.is_active and upper(coalesce(p.status,'Active'))='ACTIVE' and regexp_replace(upper(p.role),'[^A-Z0-9]','','g') in ('FO','FIELDOFFICER') and regexp_replace(upper(p.business),'[^A-Z0-9]','','g') in ('RELIANCE','RELIANCERETAIL') and exists(select 1 from public.reliance_retail_zone_fo_assignments a where a.fo_profile_id=p.id and a.effective_from<=now() and (a.effective_to is null or now()<a.effective_to));
select name,(xpath('/table/row/n/text()',report))[1]::text::bigint as row_count,(xpath('/table/row/digest/text()',report))[1]::text as digest from unnest(array['profiles','reliance_retail_store_master','reliance_retail_zones','reliance_retail_zone_fo_assignments','reliance_retail_store_zone_history','retail_unified_epoch','retail_employee_daily_attendance','retail_attendance_aop_versions','retail_provisional_access']) name cross join lateral (select query_to_xml(format('select count(*) n,md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),''[]''::jsonb)::text) digest from public.%I x',name),false,false,'' ) report) q;
rollback;
